<template>    <div>        <img v-if="!lotNumber" class="loading" src="~@/assets/images/loading.gif">        <slot v-if="!auto" :balls="balls"></slot>        <template v-if="auto">            <lotteryNumberPk10 v-if="code === 'pk10'" :balls="balls"/>            <lotteryNumberPcdd v-else-if="code === 'pcdd'" :balls="balls"/>            <lotteryNumberKsan v-else-if="code === 'ksan'" :balls="balls"/>            <lotteryNumber11x5 v-else-if="code === '11x5'" :balls="balls"/>            <lotteryNumber6hc v-else-if="code === '6hc'" :balls="balls"/>            <lotteryNumberSsc v-else-if="code === 'ssc'" :balls="balls"/>            <lotteryNumberDefault v-else :balls="balls"/>        </template>    </div></template><script>    import * as Algorithm from "@/utils/algorithm";    import lotteryNumberPk10 from "./lotteryNumberPk10";    import lotteryNumberPcdd from "./lotteryNumberPcdd";    import lotteryNumberKsan from "./lotteryNumberKsan";    import lotteryNumber11x5 from "./lotteryNumber11x5";    import lotteryNumber6hc from "./lotteryNumber6hc";    import lotteryNumberSsc from "./lotteryNumberSsc";    import lotteryNumberDefault from "./lotteryNumberDefault";    const LotteryNumberStyle = {        CIRCLE: "circle",        TEXT: "text"    };    export default {        name: "lotteryNumber",        components: {            lotteryNumberPk10,            lotteryNumberPcdd,            lotteryNumberKsan,            lotteryNumber11x5,            lotteryNumber6hc,            lotteryNumberSsc,            lotteryNumberDefault        },        props: {            auto: {                type: Boolean,                default: true            },            code: {                type: String,                default: ""            },            lotNumber: {                type: String,                default: ""            },            lastPrizeTime: {                type: String,                default: ""            },            lotStyle: {                type: String,                default: LotteryNumberStyle.CIRCLE            }        },        data() {            return {                balls: [], //{symbol, value, color, zodiac}                LotteryNumberStyle,            };        },        watch: {            lotNumber: {                deep: true,                handler(newValue, oldValue) {                    this.setLotNumber2Balls(newValue);                },                immediate: true            }        },        mounted() {            this.ckeckLotStyleProps();        },        methods: {            setLotNumber2Balls(lotNumber) {                if (!lotNumber) {                    return this.balls = [];                }                const nums = lotNumber.split(",");                if (this.code === "pcdd") {                    this.balls = Algorithm.getPcddColor(nums); //[1,2,3]                } else if (this.code === "6hc") {                    this.balls = Algorithm.getLiuheColor(nums, `${this.lastPrizeTime}`); //["49", "24", "17", "30", "40", "01+48"]                } else {                    this.balls = this.convertNormalLotNumber2Balls(nums);                }            },            convertNormalLotNumber2Balls(nums) {                return nums.map((item, idx) => {                    return {                        value: item                    };                });            },            fillZero(num) {                num = parseInt(num);                return num < 10 ? `0${num}` : num;            },            ckeckLotStyleProps() {                for (let key in LotteryNumberStyle) {                    const style = LotteryNumberStyle[key];                    if (this.lotStyle === style) {                        return;                    }                }                throw new Error("lotteryNumber lotStyle props error!");            }        }    }</script><style scoped lang="less">    @import './ball.less';    .loading {        display: block;        margin: auto;    }</style>